def regular_payment(principal, annual_rate, months) -> Decimal:
    """Standard annuity payment for a fully amortizing loan, in cents.

    Rounded *up* to the cent so the loan always retires within the original
    term (a half-cent-down rounding would leave a residual payment in
    month ``months + 1``).
    """
    p = _to_decimal(principal)
    r = _to_decimal(annual_rate) / Decimal(12)
    if r == 0:
        return _cents_up(p / Decimal(months))
    factor = (Decimal(1) + r) ** (-int(months))
    return _cents_up(p * r / (Decimal(1) - factor))

